133	inline int GetSizeByDataType(DataType data_type) {
134	  static int data_type_size[DT_MAX] = {
135	      4,                           // DT_FLOAT = 0,             float type
136	      2,                           // DT_FLOAT16 = 1,           fp16 type
137	      1,                           // DT_INT8 = 2,              int8 type
138	      4,                           // DT_INT32 = 3,             int32 type
139	      1,                           // DT_UINT8 = 4,             uint8 type
140	      -1,                          // reserved
141	      2,                           // DT_INT16 = 6,             int16 type
142	      2,                           // DT_UINT16 = 7,            uint16 type
143	      4,                           // DT_UINT32 = 8,            unsigned int32
144	      8,                           // DT_INT64 = 9,             int64 type
145	      8,                           // DT_UINT64 = 10,           unsigned int64
146	      8,                           // DT_DOUBLE = 11,           double type
147	      1,                           // DT_BOOL = 12,             bool type
148	      -1,                          // DT_STRING = 13,           string type
149	      1,                           // DT_DUAL_SUB_INT8 = 14,    dual output int8 type
150	      1,                           // DT_DUAL_SUB_UINT8 = 15,   dual output uint8 type
151	      8,                           // DT_COMPLEX64 = 16,        complex64 type
152	      16,                          // DT_COMPLEX128 = 17,       complex128 type
153	      1,                           // DT_QINT8 = 18,            qint8 type
154	      2,                           // DT_QINT16 = 19,           qint16 type
155	      4,                           // DT_QINT32 = 20,           qint32 type
156	      1,                           // DT_QUINT8 = 21,           quint8 type
157	      2,                           // DT_QUINT16 = 22,          quint16 type
158	      8,                           // DT_RESOURCE = 23,         resource type
159	      -1,                          // DT_STRING_REF = 24,       string ref type
160	      5,                           // DT_DUAL = 25,             dual output type (float + int8)
161	      8,                           // DT_VARIANT                variant type
162	      2,                           // DT_BF16 = 27,             bf16 type
163	      -1,                          // DT_UNDEFINED = 28         Used to indicate a DataType field has not been set.
164	      kDataTypeSizeBitOffset + 4,  // DT_INT4 = 29,             int4 type
165	      kDataTypeSizeBitOffset + 1,  // DT_UINT1 = 30,            uint1 type
166	      kDataTypeSizeBitOffset + 2,  // DT_INT2 = 31,             int2 type
167	      kDataTypeSizeBitOffset + 2,  // DT_UINT2 = 32,            uint2 type
168	      4,                           // DT_COMPLEX32 = 33,        complex32 type
169	      1,                           // DT_HIFLOAT8,              hifloat8 type
170	      1,                           // DT_FLOAT8_E5M2,           float8_e5m2 type
171	      1,                           // DT_FLOAT8_E4M3FN,         float8_e4m3fn type
172	      1,                           // DT_FLOAT8_E8M0,           float8_e8m0 type
173	      kDataTypeSizeBitOffset + 6,  // DT_FLOAT6_E3M2,           float6_e3m2 type, 6bit
174	      kDataTypeSizeBitOffset + 6,  // DT_FLOAT6_E2M3,           float6_e2m3 type, 6bit
175	      kDataTypeSizeBitOffset + 4,  // DT_FLOAT4_E2M1,           float4_e2m1 type, 4bit
176	      kDataTypeSizeBitOffset + 4,  // DT_FLOAT4_E1M2,           float4_e1m2 type, 4bit
177	      kDataTypeSizeBitOffset + 4,  // DT_HIFLOAT4,              hifloat4 type, 4bit
178	                                   // DT_MAX
179	  };
180	  if ((data_type < 0) || (data_type >= DT_MAX)) {
181	    return -1;
182	  }
183	  return data_type_size[data_type];
184	}
