252	/// Get format from primary and sub-format,
253	/// in bits field:
254	/// ---------------------------------------------
255	/// |   4bits  |   4bits   |   2 bytes  | 1 byte |
256	/// |----------|-----------|------------|--------|
257	/// | reserved | c0_format | sub-format | format |
258	/// ---------------------------------------------
259	/// @param primary_format
260	/// @param sub_format
261	/// @param c0_format
262	/// @return
263	inline int32_t GetFormatFromSub(int32_t primary_format, int32_t sub_format) {
264	  return static_cast<int32_t>((static_cast<uint32_t>(primary_format) & 0xffU) |
265	                              ((static_cast<uint32_t>(sub_format) & 0xffffU) << kBitNumOfOneByte));
266	}
267	
268	inline int32_t GetFormatFromC0(int32_t format, int32_t c0_format) {
269	  return static_cast<int32_t>((static_cast<uint32_t>(format) & 0xffffffU) |
270	                              ((static_cast<uint32_t>(c0_format) & 0xfU) << kBitThreeBytes));
271	}
272	
273	inline int32_t GetFormatFromSubAndC0(int32_t primary_format, int32_t sub_format, int32_t c0_format) {
274	  return static_cast<int32_t>((static_cast<uint32_t>(primary_format) & 0xffU) |
275	                              ((static_cast<uint32_t>(sub_format) & 0xffffU) << kBitNumOfOneByte) |
276	                              ((static_cast<uint32_t>(c0_format) & 0xfU) << kBitThreeBytes));
277	}
278	
279	inline int32_t GetPrimaryFormat(int32_t format) {
280	  return static_cast<int32_t>(static_cast<uint32_t>(format) & 0xffU);
281	}
282	
283	inline int32_t GetSubFormat(int32_t format) {
284	  return static_cast<int32_t>((static_cast<uint32_t>(format) & 0xffff00U) >> kBitNumOfOneByte);
285	}
286	
287	inline bool HasSubFormat(int32_t format) {
288	  return GetSubFormat(format) > 0;
289	}
290	
291	inline bool HasC0Format(int32_t format) {
292	  return ((static_cast<uint32_t>(format) & 0xf000000U) >> kBitThreeBytes) > 0;
293	}
294	
295	inline int32_t GetC0Format(int32_t format) {
296	  return static_cast<int32_t>((static_cast<uint32_t>(format) & 0xf000000U) >> kBitThreeBytes);
297	}
298	
299	inline int64_t GetC0Value(int32_t format) {
300	  if (!HasC0Format(format)) {
301	    return -1;
302	  }
303	  return static_cast<int64_t>(
304	      1 << (static_cast<int32_t>((static_cast<uint32_t>(format) & 0xf000000U) >> kBitThreeBytes) - 1));
305	}
